using System;
using System.Collections.Generic;
using System.Diagnostics;
using WallstopStudios.UnityHelpers.Core.Helper;
internal static class Program
{
    private static double sink;
    private static void Main(string[] args)
    {
        if(args.Length>0) {
            IReadOnlyList<byte> reimplemented = new InterfaceList();
            BaselineMath.TryMedian(reimplemented,out double expected);
            CandidateMath.TryMedian(reimplemented,out double actual);
            Console.WriteLine($"interface-control,expected={expected},actual={actual}");
            if(expected!=42 || actual!=expected)Environment.Exit(1);
            return;
        }
        long controlBefore=GC.GetAllocatedBytesForCurrentThread(); byte[] retained=new byte[4096]; long controlBytes=GC.GetAllocatedBytesForCurrentThread()-controlBefore; GC.KeepAlive(retained); if(controlBytes<4096)throw new Exception("Inert allocation counter");
        Console.WriteLine("allocation_control,"+controlBytes);
        Console.WriteLine("runtime,"+System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription);
        Console.WriteLine("shape,size,round,baseline_ns,candidate_ns,baseline_bytes,candidate_bytes");
        foreach(int size in new[]{8,256,4096}) {
            byte[] bytes=new byte[size];new Random(9127).NextBytes(bytes);
            List<byte> list=new List<byte>(bytes);IReadOnlyList<byte> arrayInterface=bytes,listInterface=list,wrapped=Array.AsReadOnly(bytes);
            byte[] sorted=(byte[])bytes.Clone();Array.Sort(sorted);double expected=(sorted[(size-1)/2]+sorted[size/2])*.5;
            var cases=new (string,Func<double>,Func<double>)[]{
                ("array",()=>{BaselineMath.TryMedian(bytes,out double v);return v;},()=>{CandidateMath.TryMedian(bytes,out double v);return v;}),
                ("list",()=>{BaselineMath.TryMedian(list,out double v);return v;},()=>{CandidateMath.TryMedian(list,out double v);return v;}),
                ("interface-array",()=>{BaselineMath.TryMedian(arrayInterface,out double v);return v;},()=>{CandidateMath.TryMedian(arrayInterface,out double v);return v;}),
                ("interface-list",()=>{BaselineMath.TryMedian(listInterface,out double v);return v;},()=>{CandidateMath.TryMedian(listInterface,out double v);return v;}),
                ("wrapped-control",()=>{BaselineMath.TryMedian(wrapped,out double v);return v;},()=>{CandidateMath.TryMedian(wrapped,out double v);return v;})};
            foreach(var c in cases) {
                if(c.Item2()!=expected||c.Item3()!=expected)throw new Exception("Incorrect median");
                for(int i=0;i<256;++i){sink=c.Item2()+c.Item3();}
                int n=1;while(Math.Min(Measure(c.Item2,n),Measure(c.Item3,n))<20000000)n*=2;
                for(int round=0;round<21;++round){double a,b;if(round%2==0){a=Measure(c.Item2,n);b=Measure(c.Item3,n);}else{b=Measure(c.Item3,n);a=Measure(c.Item2,n);}
                    long before=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<n;++i)sink=c.Item2();long ab=GC.GetAllocatedBytesForCurrentThread()-before;
                    before=GC.GetAllocatedBytesForCurrentThread();for(int i=0;i<n;++i)sink=c.Item3();long bb=GC.GetAllocatedBytesForCurrentThread()-before;
                    Console.WriteLine($"{c.Item1},{size},{round},{a/n:R},{b/n:R},{ab},{bb}");}
            }
        }
        GC.KeepAlive(sink);
    }
    private static double Measure(Func<double> action,int n){long start=Stopwatch.GetTimestamp();for(int i=0;i<n;++i)sink=action();return (Stopwatch.GetTimestamp()-start)*1e9/Stopwatch.Frequency;}
}

internal sealed class InterfaceList : List<byte>, IReadOnlyList<byte>
{
    public InterfaceList() : base(new byte[]{1,2,3}) { }
    int IReadOnlyCollection<byte>.Count => 3;
    byte IReadOnlyList<byte>.this[int index] => 42;
}

